import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.Bqa2y7hU.js";const p=JSON.parse('{"title":"内置插件一览","description":"随框架提供的常用插件：群管、消息发送、自定义 API、关键词回复、入群欢迎等，各自能做什么、需不需要平台权限。","frontmatter":{"title":"内置插件一览","description":"随框架提供的常用插件：群管、消息发送、自定义 API、关键词回复、入群欢迎等，各自能做什么、需不需要平台权限。"},"headers":[],"relativePath":"console/builtin-plugins.md","filePath":"console/builtin-plugins.md","lastUpdated":1789487229000}'),l={name:"console/builtin-plugins.md"};function i(d,t,n,s,h,c){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="内置插件一览" tabindex="-1">内置插件一览 <a class="header-anchor" href="#内置插件一览" aria-label="Permalink to &quot;内置插件一览&quot;">​</a></h1><p>这些插件随框架提供，在控制台「插件市场」里可以直接装到你的机器人上。每一条都标了<strong>是否需要平台额外开权限</strong>——需要开权限的功能，没开通时的表现是&quot;操作失败&quot;，而不是静默无效。</p><div class="tip custom-block"><p class="custom-block-title">以市场为准</p><p>插件会持续增加和更新，<strong>本页只是导读</strong>；某个插件是否可用、当前版本、需要什么权限，以「插件市场」里实际列出的为准。</p></div><h2 id="社群管理" tabindex="-1">社群管理 <a class="header-anchor" href="#社群管理" aria-label="Permalink to &quot;社群管理&quot;">​</a></h2><h3 id="群管" tabindex="-1">群管 <a class="header-anchor" href="#群管" aria-label="Permalink to &quot;群管&quot;">​</a></h3><p>功能最全的一个，装到群管类机器人上基本够用：</p><p>功能覆盖 12 个子系统：内容检测与处罚（违禁词 / 链接 / 卡片 / 转发 / 手机号 / QQ 号 / 刷屏 / 全撤模式）、 处罚升级（警告、阶梯禁言、违规记录）、入群验证与审批、成员处置（禁言 / 踢出 / 针对撤回）、黑白名单、 <strong>授权系统</strong>（按群授权 30 天 / 90 天 / 永久 + 到期提醒）、问答、发言统计、签到、定时播报、入群退群提示、 主人与副主。<strong>完整说明见 <a href="/RuaBot.Doc/console/group-admin">群管使用指南</a>。</strong></p><ul><li><strong>有插件面板</strong>：词库、名单、功能开关、入群策略、回复模板、审计日志都在网页上配。</li><li><strong>菜单可以改成你自己的样子</strong>：面板「菜单设置」里，每一页就一个文本框——框里写什么、群里就收到什么。改菜单只影响显示，不会禁用任何指令。详见 <a href="/RuaBot.Doc/console/group-admin#九-自定义菜单内容">群管使用指南</a>。</li><li><strong>按钮与 Markdown</strong>：QQ 官方平台下，入群审批播报会带可点击的按钮；其它平台用文字指令（如回复「同意 1」）。</li><li><strong>需要平台权限</strong>：禁言、踢人、查群成员、入群审批这些依赖平台接口，机器人还需是群管理员。见 <a href="/RuaBot.Doc/reference/capabilities">平台能力码</a>。</li><li><strong>默认值</strong>：授权模式默认关闭、榜单记录默认关闭、签到默认开启——都不影响既有群。</li></ul><h3 id="违禁词" tabindex="-1">违禁词 <a class="header-anchor" href="#违禁词" aria-label="Permalink to &quot;违禁词&quot;">​</a></h3><p>轻量版内容拦截：命中违禁词自动撤回，可选自动禁言，支持全局词库与分群词库。不需要面板，词库用群内指令维护。</p><h3 id="针对撤回" tabindex="-1">针对撤回 <a class="header-anchor" href="#针对撤回" aria-label="Permalink to &quot;针对撤回&quot;">​</a></h3><p>把指定成员加入「针对名单」，之后他在群里发的消息会被自动撤回。适合处理屡教不改的成员。</p><h3 id="入群欢迎" tabindex="-1">入群欢迎 <a class="header-anchor" href="#入群欢迎" aria-label="Permalink to &quot;入群欢迎&quot;">​</a></h3><p>群成员进群时发送欢迎语，支持黑白名单、每日次数上限与文案模板。</p><h2 id="消息与互动" tabindex="-1">消息与互动 <a class="header-anchor" href="#消息与互动" aria-label="Permalink to &quot;消息与互动&quot;">​</a></h2><h3 id="消息发送" tabindex="-1">消息发送 <a class="header-anchor" href="#消息发送" aria-label="Permalink to &quot;消息发送&quot;">​</a></h3><p><strong>网页直接给群发消息</strong>的控制台：左侧群列表、右侧聊天窗口，不用加插件、不用写指令。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>群列表</td><td>机器人收到过消息的群会自动出现在列表里，不需要手工配置</td></tr><tr><td>聊天窗口</td><td>显示该群最近的消息，<strong>收到和发出的都显示</strong>；从这里发出的消息会立刻出现在气泡流里</td></tr><tr><td>被动消息</td><td>用该群<strong>近 5 分钟</strong>内的消息作为回复凭证发送，不占用主动消息配额</td></tr><tr><td>主动消息</td><td>不需要回复凭证，但<strong>需要平台授权</strong>；没权限时面板会直接拒绝并提示改用被动消息</td></tr><tr><td>消息类型</td><td>文本、Markdown、图片（填图片链接）、图文混合</td></tr></tbody></table><p>几个使用要点：</p><ul><li><strong>Markdown 只在 QQ 官方平台渲染</strong>，其它平台会按纯文本发出（面板上有提示）。</li><li>图片只支持 <strong>URL</strong>，不是上传文件；把图片链接填进去即可。</li><li>「被动消息」为什么要求近 5 分钟：平台对引用原消息的被动回复豁免主动频控，超过 5 分钟凭证就失效了。这时改用「主动消息」。</li><li>面板显示的聊天记录会<strong>保留</strong>：每个群最近 50 条落库，服务重启后仍然能看到（更早的按条数自动滚动淘汰）。</li></ul><h3 id="自定义-api" tabindex="-1">自定义 API <a class="header-anchor" href="#自定义-api" aria-label="Permalink to &quot;自定义 API&quot;">​</a></h3><p>不用写代码，把「一段指令」接到「任意外部 HTTP 接口」上，并把返回结果按模板变成文本或图片回发。支持多步链式调用（前一个接口的结果喂给后一个）、变量替换与条件分支。<strong>有插件面板</strong>，配置在网页里完成。</p><h3 id="关键词回复" tabindex="-1">关键词回复 <a class="header-anchor" href="#关键词回复" aria-label="Permalink to &quot;关键词回复&quot;">​</a></h3><p>最简单的自动回复：群里出现某个关键词就回一段固定文本。<strong>有插件面板</strong>。</p><h3 id="多平台点歌" tabindex="-1">多平台点歌 <a class="header-anchor" href="#多平台点歌" aria-label="Permalink to &quot;多平台点歌&quot;">​</a></h3><p>支持网易云、QQ 音乐、汽水、酷我四个平台：搜索 → 按钮选歌 → 歌词 / 卡片 / 下载链接。</p><h3 id="聚合视频解析" tabindex="-1">聚合视频解析 <a class="header-anchor" href="#聚合视频解析" aria-label="Permalink to &quot;聚合视频解析&quot;">​</a></h3><p>群里有人发抖音 / 快手 / B 站的分享链接时，机器人自动把它<strong>解析成无水印的直链</strong>回发出来——视频会直接以视频消息发出，图集会逐张或合并发出，不用点开原链接。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>支持平台</td><td>抖音（<code>v.douyin.com</code>）、快手（<code>v.kuaishou.com</code>）、B 站（<code>b23.tv</code>），每个平台可单独开关</td></tr><tr><td>图集处理</td><td>多图内容逐张发送；QQ 官方平台下可开启「图集 Markdown 合并发送」，把整组图塞进一条消息，绕开被动回复的条数限制</td></tr><tr><td>发送效果</td><td>先回一条含封面、标题、作者、简介的说明，再发视频本体 / 图集图片，内容以解析服务返回的为准</td></tr><tr><td>失败兜底</td><td>网络异常回「API请求失败，请检查网络」；接口返回失败时回它给的提示文案，不会静默失败</td></tr></tbody></table><p><strong>需要先配置 API 密钥</strong>：这个插件走的是第三方聚合解析服务（<code>api-v2.yuafeng.cn</code>），需要去该服务申请一个密钥，填到插件设置里才能用。<strong>没有密钥时插件不工作</strong>。</p><ul><li><strong>有配置表单</strong>：在机器人详情页 → 插件 Tab → 该插件的「配置」里填密钥、开关平台、调整图集发送参数。</li><li><strong>不需要平台额外开权限</strong>：解析本身是纯 HTTP 调用；只有发送媒体时依赖平台能力（见 <a href="/RuaBot.Doc/reference/capabilities">平台能力码</a>）。</li></ul><h3 id="群禁言" tabindex="-1">群禁言 <a class="header-anchor" href="#群禁言" aria-label="Permalink to &quot;群禁言&quot;">​</a></h3><p>独立的小工具：群内发「禁言 @某人 分钟」或「解禁 @某人」。功能和群管插件里的禁言重叠，二选一即可。</p><h2 id="群信息与工具" tabindex="-1">群信息与工具 <a class="header-anchor" href="#群信息与工具" aria-label="Permalink to &quot;群信息与工具&quot;">​</a></h2><h3 id="群状态-群信息" tabindex="-1">群状态 / 群信息 <a class="header-anchor" href="#群状态-群信息" aria-label="Permalink to &quot;群状态 / 群信息&quot;">​</a></h3><p>查询群的名称、成员数、机器人在群里的角色、是否可主动推送消息、入群时间等信息。<strong>排错时很有用</strong>：怀疑权限问题时，先看一眼机器人当前的群内身份与授权状态。</p><h3 id="我的-id" tabindex="-1">我的 ID <a class="header-anchor" href="#我的-id" aria-label="Permalink to &quot;我的 ID&quot;">​</a></h3><p>回复发送者自己的标识（群里会附带群标识）。做接口联调、填「针对名单」时取标识用得上。</p><h3 id="全量申请" tabindex="-1">全量申请 <a class="header-anchor" href="#全量申请" aria-label="Permalink to &quot;全量申请&quot;">​</a></h3><p>生成「群全量消息授权」的深链，群主在 QQ 里点开即可授权。</p><div class="warning custom-block"><p class="custom-block-title">不授权会怎样</p><p>QQ 官方平台默认只把 <strong>@ 机器人</strong>的消息推给它。没做全量授权时，群管、关键词回复这类需要看全部消息的插件都不会触发。</p></div><h3 id="速度测试" tabindex="-1">速度测试 <a class="header-anchor" href="#速度测试" aria-label="Permalink to &quot;速度测试&quot;">​</a></h3><p>回复框架收到消息到发出回复的耗时，用来判断&quot;慢&quot;是慢在网络还是慢在插件。</p><h2 id="开发者示例" tabindex="-1">开发者示例 <a class="header-anchor" href="#开发者示例" aria-label="Permalink to &quot;开发者示例&quot;">​</a></h2><p>下面几个主要是给插件开发者看的参考实现，普通用户可以忽略：</p><table tabindex="0"><thead><tr><th>插件</th><th>用途</th></tr></thead><tbody><tr><td>回声</td><td>最小示例：被 @ 或私聊时原样回显，20 行代码</td></tr><tr><td>面板演示</td><td>演示插件自带 Web 面板怎么写（配置读写 + 动态接口）</td></tr><tr><td>能力探针</td><td>群内发 <code>/cap &lt;能力码&gt;</code> 直接调用平台能力并回显原始结果，调接口时非常好用</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/plugins">插件市场与安装</a>：怎么把插件装到机器人上</li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a>：机器人详情页的五个 Tab</li><li><a href="/RuaBot.Doc/faq">群管怎么用</a>：常见问题与排查</li></ul>',48)])])}const b=a(l,[["render",i]]);export{p as __pageData,b as default};
